import pathlib,sys,json,numpy as np,pandas as pd
from scipy import stats
import matplotlib;matplotlib.use('Agg')
import matplotlib.pyplot as plt
O=pathlib.Path(sys.argv[1]);R=O/'results/screen';s=pd.read_csv(R/'summary.tsv',sep='\t');p=pd.read_csv(R/'patient_effects.tsv',sep='\t');q=pd.read_csv(R/'sample_QC.tsv',sep='\t');e=pd.read_csv(R/'section_effects.tsv',sep='\t');cov=pd.read_csv(R/'contrast_eligibility.tsv',sep='\t')
main=s[(s.scope=='baseline')&(s.gene=='CGNL1')&(s.contrast=='tumor_near300_vs_far600')&(s.method=='pseudobulk')].iloc[0]
fig,axs=plt.subplots(2,2,figsize=(12.5,9));b=p[(p.scope=='baseline')&(p.gene=='CGNL1')];col=['#D06B45','#26828E']
for ax,contrast,title in [(axs[0,0],'tumor_near300_vs_far600','CGNL1: near liver vs tumor interior'),(axs[0,1],'hepatic_lobule_vs_macro_tumor','CGNL1: hepatic lobule vs tumor region'),(axs[1,0],'macro_stroma_vs_macro_tumor','CGNL1: metastatic stroma vs tumor region')]:
 z=b[(b.contrast==contrast)&(b.method=='pseudobulk')].sort_values('patient');vals=z.effect.to_numpy();ax.bar(np.arange(len(z)),vals,color=[col[0] if x>0 else col[1] for x in vals]);ax.axhline(0,c='#334A58',lw=.8);ax.set_xticks(np.arange(len(z)),['P'+str(int(i)) for i in z.patient]);ax.set_ylabel('Patient mean difference in log2(CPM+1)');ax.set_title(title+'\nn='+str(len(z))+' independent patients',fontsize=11);ax.spines[['top','right']].set_visible(False)
z=b[(b.contrast=='tumor_near300_vs_far600')&b.method.isin(['spot_mean','score_adjusted'])].pivot(index='patient',columns='method',values='effect').dropna();ax=axs[1,1]
for _,v in z.iterrows():ax.plot([0,1],[v.spot_mean,v.score_adjusted],'-o',color='#6B8491',alpha=.7,markersize=4)
ax.axhline(0,c='#334A58',lw=.8);ax.set_xticks([0,1],['Unadjusted spot mean','Score-adjusted coefficient']);ax.set_ylabel('Difference in spot-level log2(CPM+1)');ax.set_title('CGNL1: composition-score sensitivity\nMatched patient set n='+str(len(z)),fontsize=11);ax.spines[['top','right']].set_visible(False)
fig.suptitle('GSE294385 | Non-recurrence sections | Patient-level spatial screen',fontsize=14);fig.tight_layout(rect=(0,0,1,.96));fig.savefig(R/'figures/CGNL1_patient_summary.png',dpi=180);fig.savefig(R/'figures/CGNL1_patient_summary.svg');plt.close(fig)
# Independent checks reconstruct the primary endpoint from spot-level cached counts and library sizes.
a=pd.read_csv(R/'spot_target_coordinates.tsv.gz',sep='\t');assert not a.duplicated(['sample','barcode']).any();assert len(q)==24 and q.patient.nunique()==11;checks=[];calc=[]
for name,v in a[~a.recurrence].groupby('sample'):
 t=v[(v.Layer3=='Liver macrometastasis tumor')&v.QC_pass];near=t[t.distance_to_hepatic_um<=300+1e-6];far=t[t.distance_to_hepatic_um>=600-1e-6]
 if len(near)<20 or len(far)<20:continue
 d=np.log2(1+near.CGNL1_counts.sum()/near.UMI.sum()*1e6)-np.log2(1+far.CGNL1_counts.sum()/far.UMI.sum()*1e6);orig=e[(e['sample']==name)&(e.gene=='CGNL1')&(e.contrast=='tumor_near300_vs_far600')&(e.method=='pseudobulk')].iloc[0];assert abs(d-orig.effect)<1e-10;calc.append({'patient':int(v.patient.iloc[0]),'effect':d});checks.append({'sample':name,'primary_reconstruction_error':float(abs(d-orig.effect))})
x=pd.DataFrame(calc).groupby('patient').effect.mean();assert abs(x.mean()-main.mean_effect)<1e-10
if len(x)>=10:assert abs(stats.ttest_1samp(x,0).pvalue-main.P)<1e-10
(R/'PRIMARY_RECHECK.json').write_text(json.dumps({'pass':True,'raw_count_endpoint_reconstruction':checks,'n_patients':len(x),'mean_effect':float(x.mean())},indent=2))
# Decision language depends on the prespecified primary result, not a selected distance.
if main.mean_effect>0 and main.n_patients>=10 and main.P<.05:decision='患者级主分析支持：肿瘤标注区域的CGNL1在近肝小叶侧升高。'
elif main.mean_effect<0 and main.n_patients>=10 and main.P<.05:decision='患者级主分析显示近肝小叶侧CGNL1降低，不支持原先的近肝侧上调假设。'
elif main.mean_effect>0 and main.positive/main.n_patients>=.7:decision='探索性提示近肝小叶侧CGNL1升高，但尚不足以形成稳健的患者级空间结论。'
else:decision='当前数据不支持CGNL1在肿瘤近肝小叶侧一致升高。'
def num(v):return 'NA' if pd.isna(v) else f'{v:.5g}'
def table(z,cols):
 out=['| '+' | '.join(cols)+' |','|'+'|'.join(['---']*len(cols))+'|']
 for row in z[cols].itertuples(index=False,name=None):out.append('| '+' | '.join(num(v) if isinstance(v,(float,np.floating)) else str(v) for v in row)+' |')
 return '\n'.join(out)
text=['# CGNL1肝转移空间初筛结果','日期：2026-09-24','## 结论',decision,'本轮完成GSE294385全部24张肝转移切片的初筛，来自11名患者。主分析使用19张非复发切片；独立n以实际满足比较门槛的患者数为准。作者资料尚未逐例确认结肠/直肠来源，因此这是结肠癌课题的CRC空间支持证据。','## 预设主要终点','同一切片的作者“肝宏转移肿瘤”区域中，比较距最近肝小叶spot中心≤300微米与≥600微米的部分。每组至少20个QC合格spot；先计算切片伪bulk差，再等权汇总到患者。','主基因CGNL1、主距离和主比较预先指定，单一主要终点不需要FDR。这个分析不是全基因组筛选；另外3候选及其他比较分别在预设同类家族中BH校正。',table(pd.DataFrame([main]),['n_patients','positive','negative','mean_effect','median_effect','CI_low','CI_high','P','LOO_min','LOO_max']),'效应单位为log2(CPM+1)差。小于10名有效患者的比较不报告推断P或FDR。逐患者剔除范围反映点估计稳健性，不表示每次剔除后均显著。','## 距离与组成敏感性',table(s[(s.scope=='baseline')&(s.gene=='CGNL1')&s.contrast.str.startswith('tumor_')],['contrast','method','n_patients','positive','negative','mean_effect','CI_low','CI_high','P','FDR']),'pseudobulk是区域汇总表达差；spot_mean与score_adjusted均为spot层面的log2(CPM+1)均值/系数，二者可比较调整幅度，不能与pseudobulk幅度直接等同。所有推断均在患者效应上完成，未用spot数量增加n。','组成模型加入肝、间质、上皮、内皮标记表达评分及log UMI。这些是表达代理，不是真实细胞比例，且可与生物学状态重叠。调整后减弱不能直接证明污染，保留关联也不能单独证明癌细胞内调控。','## 病理区域来源与病灶状态',table(s[(s.scope=='baseline')&(s.gene=='CGNL1')&~s.contrast.str.startswith('tumor_')],['contrast','n_patients','positive','negative','mean_effect','median_effect','CI_low','CI_high','P','FDR']),'hepatic_lobule_vs_macro_tumor：肝小叶区域减宏转移肿瘤区域；macro_stroma_vs_macro_tumor：转移基质减肿瘤；micro_tumor_vs_macro_tumor：同片微转移肿瘤减宏转移肿瘤。微转移比较不代表纵向演变，也不将一个病灶的多个spot当成独立生物学重复。','## 四个候选的同口径结果',table(s[(s.scope=='baseline')&(s.contrast=='tumor_near300_vs_far600')&(s.method=='pseudobulk')],['gene','n_patients','positive','negative','mean_effect','median_effect','P','FDR','family']),'CGNL1为预设主基因；其他3候选是补充筛查，本轮空间结果不能替代其此前独立bulk验证情况。','## 全部敏感性与复发切片','全部模型、阈值和含复发样本的敏感性保存在summary.tsv。复发及重复切片仍按原患者汇总，不增加独立n。',table(s[(s.scope=='all_timepoints')&(s.gene=='CGNL1')&(s.method=='pseudobulk')],['contrast','n_patients','positive','negative','mean_effect','P','FDR']),'## 方法与数据完整性','每spot原始UMI≥500、检出基因≥200；按作者病理标签确定区域，CGNL1不参与区域定义。Visium为多细胞spot分辨率，本轮结果属于病理区域证据，不能直接称为纯癌细胞证据。','使用array_col×50、array_row×50×sqrt(3)转换为微米坐标，最近邻间距100微米；图像像素坐标仅用于显示。初版基于spot_diameter_fullres的缩放在两批次产生约84.6/91.5微米间距，与已知阵列间距不符，已修正；原单张pilot结果不采用。距离阈值未因候选效应调整。','IX批次缺KRT19，M-ST批次缺KRT18，因此在查看候选比较结果前，将上皮评分统一为共同可测的EPCAM/KRT8，保存原方案和修订记录。两基因代理的分辨能力有限，不能写成完成细胞解卷积。','本轮尚未进行细胞分辨率来源确认、独立外部空间复现或CGNL1上游因果分析。交界邻近不等于直接细胞接触；邻近转录本扩散及混合spot仍需后续处理。','24份输入下载结果、SHA256、逐切片QC、区域纳入表和全部患者效应均保留。主终点已从缓存原始target counts/总UMI独立重建并核对。','## 图件','![患者级结果](results/screen/figures/CGNL1_patient_summary.png)','每张切片的病理叠加、CGNL1表达和近/远肝分组见results/screen/figures。','## 文件位置','本地：C:/Users/31937/CRC_routes_20260923/spatial_v3；服务器：/mnt/BioDisk/wangmingyuan/GI_preanalysis_20260923/CRC_routes_v1/spatial_v3。']
(O/'空间初筛结果.md').write_text('\n\n'.join(text),encoding='utf-8-sig');print(decision);print(main.to_string());print('REPORT_COMPLETE',flush=True)
